use std::{collections::HashSet,fs};
use lex_core::Provision;
fn main(){
 let all:Vec<Provision>=serde_json::from_str(&fs::read_to_string("/Users/jr/Dev/lex-mex/corpus/mx/reg-lan/provisions.json").unwrap()).unwrap();
 let parent="urn:lex-mx:federal:statute:lan";
 let named="urn:lex-mx:federal:statute:lmtr";
 let other="urn:lex-mx:federal:statute:lft";
 let opts=lex_parse::ReferenceOptions{policy:lex_parse::InstrumentContextPolicy::SentenceEarliestMarker{internal_markers:vec!["de este reglamento".into(),"del presente reglamento".into()],external_instruments:vec![("ley en materia de telecomunicaciones y radiodifusión".into(),named.into()),("ley federal del trabajo".into(),other.into())]},transitory_citations:true,same_article_fractions:true,relative_references:true,historical_targets:vec![],parent_instrument:Some(parent.into())};
 for text in [
 "Se aplicará el artículo 1 de la Ley.",
 "Se aplicará el artículo 1 de la Ley Federal del Trabajo.",
 "Se aplicará el artículo 1 de la Ley en Materia de Telecomunicaciones y Radiodifusión.",
 "La Ley Federal del Trabajo es el ordenamiento en comento. Se aplicará el artículo 1 de la Ley en comento.",
 "La Ley Federal del Trabajo es el ordenamiento al que se hace referencia. Se aplicará el artículo 1 de la Ley que se cita.",
 "Se aplicará el artículo 1 de la Ley vigente hasta el 31 de diciembre de 1990.",
 "Se aplicará el artículo 1 de la Ley en vigor al 31 de diciembre de 1990.",
 "Se aplicará el artículo 1 de la Ley que estaba vigente al 31 de diciembre de 1990.",
 "Se aplicará el artículo 1 de dicha Ley.",
 "Se aplicará el artículo 1 de la Ley y de este Reglamento.",
 ] {
 let mut ps=all[..3].to_vec();ps[1].text=text.into();let mut targets:HashSet<_>=ps.iter().map(|p|p.id.clone()).collect();
 for target in [parent,named,other]{targets.insert(format!("{target}:article:1"));}
 let refs=lex_parse::extract_references(&ps,None,&opts,&targets).unwrap();println!("INPUT: {text}");for e in refs.iter().filter(|e|e.source_provision_id==ps[1].id){println!("{} -> {} {:?}",e.source_span,e.target_provision_id,e.resolution_status);}
 }

