use std::collections::HashSet;
use lex_parse::{DiputadosOptions, ReferenceOptions, InstrumentContextPolicy};
fn main() {
 let reg="urn:lex-mx:federal:regulation:reg-lan";
 let parent="urn:lex-mx:federal:statute:lan";
 let options=ReferenceOptions {policy:InstrumentContextPolicy::SentenceEarliestMarker{internal_markers:vec!["de este reglamento".into()],external_instruments:vec![]}, transitory_citations:true,same_article_fractions:true,relative_references:true,historical_targets:vec![],parent_instrument:Some(parent.into())};
 let known=HashSet::from([format!("{parent}:article:10")]);
 let mut rows=Vec::new();
 for (label,text,expected) in [
  ("bare_current_control","Se aplicará el artículo 10 de la Ley.",1),
  ("bare_dated_control","Se aplicará el artículo 10 de la Ley vigente hasta el 31 de diciembre de 2001.",0),
  ("curly_quoted_dated","Se aplicará el artículo 10 de la “Ley” vigente hasta el 31 de diciembre de 2001.",0),
  ("straight_quoted_dated","Se aplicará el artículo 10 de la \"Ley\" vigente hasta el 31 de diciembre de 2001.",0),
  ("bare_anaphoric_control","Se aplicará el artículo 10 de la Ley en cita.",0),
  ("quoted_anaphoric","Se aplicará el artículo 10 de la “Ley” en cita.",0),
 ] {
  let source=format!("Artículo 1.- {text}");
  let doc=lex_parse::parse_diputados(&source,&DiputadosOptions{instrument_id:reg.into(),header_lines:vec![],stop_markers:vec![],annex_markers:vec![],separate_enactment:false,nested_instrument:None},"2026-01-01".parse().unwrap()).unwrap();
  let edges=lex_parse::extract_references(&doc.provisions,None,&options,&known).unwrap();
  rows.push(serde_json::json!({"case":label,"text":text,"expected_edges":expected,"actual_edges":edges,"count_matches":edges.len()==expected}));
 }
 println!("{}",serde_json::to_string_pretty(&rows).unwrap());
}
